import React from 'react';
import axios from 'axios';

const JobItem = ({ job, fetchJobs }) => {
    const handleDelete = async () => {
        await axios.delete(`/api/jobs/${job._id}`);
        fetchJobs();
    };

    return (
        <div>
            <h3>{job.role} at {job.company}</h3>
            <p>Status: {job.status}</p>
            <p>Date of Application: {new Date(job.dateOfApplication).toLocaleDateString()}</p>
            <a href={job.link} target="_blank" rel="noopener noreferrer">View Job</a>
            <button onClick={handleDelete}>Delete</button>
        </div>
    );
};

export default JobItem;
